/// <param name="e"></param>
[FormDataSourceEventHandler(formDataSourceStr(smmActivities, smmActivities), FormDataSourceEventType::Initialized)]
public static void smmActivities_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
{
   sender.queryBuildDataSource().sortClear();
   sender.queryBuildDataSource().addSortField(fieldNum(smmActivities,StartDateTime),SortOrder::Descending);
}
